#include<bits/stdc++.h>
#define int long long
using namespace std;
int c[11111];
vector<int>v[11111];
int dfs(int p,int ce){
	for(int i=0;i<v[p].size();i++){
		if(c[v[p][i]]==0){
			c[v[p][i]]=2-ce+1;
			return dfs(v[p][i],2-ce+1);
		}else if(c[v[p][i]]==c[p]){
			return 0;
		}
	}
	return 1;
}
signed main() {
	ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);
	int n,m;
	cin>>n>>m;
	for(int i=1;i<=m;i++){
		int x,y;
		cin>>x>>y;
		v[x].push_back(y);
		v[y].push_back(x);
	}
	c[1]=1;
	cout<<(dfs(1,1)?"yes":"no");
	return 0;
}
